package com.mendes.scheduling_platform.user; import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.security.TenantContext; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/users") public class UserController { private final UserRepository repo; private final PasswordEncoder encoder; public UserController(UserRepository r,PasswordEncoder e){repo=r;encoder=e;} record Request(@NotBlank String name,@Email @NotBlank String email,@Size(min=8) String password,@NotNull User.Role role){} @GetMapping List<User> list(){return repo.findAllByTenantId(TenantContext.getRequired());} @PostMapping @PreAuthorize("hasAnyRole('OWNER','MANAGER')") User create(@Valid @RequestBody Request r){Long t=TenantContext.getRequired();if(repo.existsByTenantIdAndEmailIgnoreCase(t,r.email()))throw new BusinessException("E-mail já cadastrado");User u=new User();u.setTenantId(t);u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(r.role());return repo.save(u);} }
